    /**
     * Returns the number of rows matching criteria, joining all related tables
     *
     * @param      Criteria $criteria
     * @param      boolean $distinct Whether to select only distinct columns; deprecated: use Criteria->setDistinct() instead.
     * @param      PropelPDO $con
     * @param      String    $join_behavior the type of joins to use, defaults to Criteria::LEFT_JOIN
     * @return int Number of matching rows.
     */
    public static function doCountJoinAll(Criteria $criteria, $distinct = false, PropelPDO $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        // we're going to modify criteria, so copy it first
        $criteria = clone $criteria;

        // We need to set the primary table name, since in the case that there are no WHERE columns
        // it will be impossible for the BasePeer::createSelectSql() method to determine which
        // tables go into the FROM clause.
        $criteria->setPrimaryTableName(ComEnviadaPeer::TABLE_NAME);

        if ($distinct && !in_array(Criteria::DISTINCT, $criteria->getSelectModifiers())) {
            $criteria->setDistinct();
        }

        if (!$criteria->hasSelectClause()) {
            ComEnviadaPeer::addSelectColumns($criteria);
        }

        $criteria->clearOrderByColumns(); // ORDER BY won't ever affect the count

        // Set the correct dbName
        $criteria->setDbName(ComEnviadaPeer::DATABASE_NAME);

        if ($con === null) {
            $con = Propel::getConnection(ComEnviadaPeer::DATABASE_NAME, Propel::CONNECTION_READ);
        }

        $criteria->addJoin(ComEnviadaPeer::CIUDAD_ID, CiudadPeer::CIUDAD_ID, $join_behavior);

        $criteria->addJoin(ComEnviadaPeer::DEPENDENCIA_ID, DependenciaPeer::DEPENDENCIA_ID, $join_behavior);

        $criteria->addJoin(ComEnviadaPeer::ESTADOCOMENVIADA_ID, EstadoComEnviadaPeer::ESTADOCOMENVIADA_ID, $join_behavior);

        $criteria->addJoin(ComEnviadaPeer::EMPRESA_MENSAJERIA_ID, EmpresaMensajeriaPeer::EMPRESA_MENSAJERIA_ID, $join_behavior);

        $criteria->addJoin(ComEnviadaPeer::REGIONAL_ID, RegionalPeer::REGIONAL_ID, $join_behavior);

        $criteria->addJoin(ComEnviadaPeer::PERIODO_ID, PeriodoPeer::PERIODO_ID, $join_behavior);

        $criteria->addJoin(ComEnviadaPeer::ESTADODIGITALIZACION_ID, EstadoDigitalizacionPeer::ESTADODIGITALIZACION_ID, $join_behavior);

        $criteria->addJoin(ComEnviadaPeer::IDIOMA_ID, IdiomaPeer::IDIOMA_ID, $join_behavior);

        $criteria->addJoin(ComEnviadaPeer::PLANTILLASCOM_ID, PlantillasComPeer::PLANTILLASCOM_ID, $join_behavior);

        $criteria->addJoin(ComEnviadaPeer::TIPOFIRMADIGITAL_ID, TipoFirmaDigitalPeer::TIPOFIRMADIGITAL_ID, $join_behavior);

        $criteria->addJoin(ComEnviadaPeer::TIPOPROCESOCOM_ID, TipoProcesoComPeer::TIPOPROCESOCOM_ID, $join_behavior);

        $criteria->addJoin(ComEnviadaPeer::SERVICIO_ID, ServicioPeer::SERVICIO_ID, $join_behavior);

        $criteria->addJoin(ComEnviadaPeer::PRIORIDADCOM_ID, PrioridadComPeer::PRIORIDADCOM_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseComEnviadaPeer', $criteria, $con);
        }

        $stmt = BasePeer::doCount($criteria, $con);

        if ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $count = (int) $row[0];
        } else {
            $count = 0; // no rows returned; we infer that means 0 matches.
        }
        $stmt->closeCursor();

        return $count;
    }

