                    $obj11->hydrate($row, $startcol11);
                    TipoFirmaDigitalPeer::addInstanceToPool($obj11, $key11);
                } // if $obj11 already loaded

                // Add the $obj1 (ComEnviada) to the collection in $obj11 (TipoFirmaDigital)
                $obj11->addComEnviada($obj1);

            } // if joined row is not null

                // Add objects for joined TipoProcesoCom rows

                $key12 = TipoProcesoComPeer::getPrimaryKeyHashFromRow($row, $startcol12);
                if ($key12 !== null) {
                    $obj12 = TipoProcesoComPeer::getInstanceFromPool($key12);
                    if (!$obj12) {
    
                        $cls = TipoProcesoComPeer::getOMClass();

                    $obj12 = new $cls();
                    $obj12->hydrate($row, $startcol12);
                    TipoProcesoComPeer::addInstanceToPool($obj12, $key12);
                } // if $obj12 already loaded

                // Add the $obj1 (ComEnviada) to the collection in $obj12 (TipoProcesoCom)
                $obj12->addComEnviada($obj1);

            } // if joined row is not null

                // Add objects for joined Servicio rows

                $key13 = ServicioPeer::getPrimaryKeyHashFromRow($row, $startcol13);
                if ($key13 !== null) {
                    $obj13 = ServicioPeer::getInstanceFromPool($key13);
                    if (!$obj13) {
    
                        $cls = ServicioPeer::getOMClass();

                    $obj13 = new $cls();
                    $obj13->hydrate($row, $startcol13);
                    ServicioPeer::addInstanceToPool($obj13, $key13);
                } // if $obj13 already loaded

                // Add the $obj1 (ComEnviada) to the collection in $obj13 (Servicio)
                $obj13->addComEnviada($obj1);

            } // if joined row is not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }

